/**
 * Where each creature's mouth is, as a fraction of its image's width and
 * height. Generated by `scripts/build-mouths.mjs` — do not edit by hand.
 *
 * Feeding carries the food to these coordinates. A single centred target was
 * wrong by up to 9.5% of the image width, because every revealed creature is
 * posed with its head turned away from centre.
 */
const MOUTHS: Record<string, [number, number]> = {
  "egg-1-pink": [0.4997, 0.5274],
  "egg-1": [0.4994, 0.5277],
  "egg-2-pink": [0.5000, 0.5229],
  "egg-2": [0.5002, 0.5226],
  "egg-3-pink": [0.4712, 0.5121],
  "egg-3": [0.4711, 0.5127],
  "fire-1": [0.4159, 0.4686],
  "fire-2": [0.4435, 0.4647],
  "fire-3": [0.4437, 0.5385],
  "forest-1": [0.4351, 0.5425],
  "forest-2": [0.4573, 0.4854],
  "forest-3": [0.4081, 0.4927],
  "ice-1": [0.4293, 0.4659],
  "ice-2": [0.4777, 0.4855],
  "ice-3": [0.4416, 0.4682],
  "light-1": [0.4371, 0.5361],
  "light-2": [0.4652, 0.4803],
  "light-3": [0.4441, 0.5085],
  "star-1": [0.4316, 0.5731],
  "star-2": [0.4574, 0.4995],
  "star-3": [0.4095, 0.4939],
  "water-1": [0.4306, 0.4941],
  "water-2": [0.4590, 0.5230],
  "water-3": [0.4054, 0.4927],
  "wind-1": [0.4296, 0.4805],
  "wind-2": [0.4706, 0.5332],
  "wind-3": [0.4071, 0.4899],
};

/** Falls back to the middle of the spread for art with no measurement. */
const FALLBACK: [number, number] = [0.5, 0.48];

export function mouthOf(art: string): [number, number] {
  const id = art
    .replace(/^.*\//, "")
    .replace(/-(flat|sad|sleepy)(?=(-pink)?\.webp$)/, "")
    .replace(/\.webp$/, "");
  return MOUTHS[id] ?? FALLBACK;
}
